"""Add future QA cases without changing any previous case or user's results."""
import argparse,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def main():
    a=argparse.ArgumentParser();a.add_argument('--manifest',type=Path,required=True);args=a.parse_args()
    m=json.loads(args.manifest.read_text(encoding='utf-8'));pair={'bundle':m['distributions']['frontend']['app.js'],'dll':m['distributions']['server']['RackClick.Server.dll']}
    p=ROOT/'docs/QA-CASOS-WASCAR.json';c=json.loads(p.read_text(encoding='utf-8'));before=c['cases'][:62]
    intro='Sólo si indica DISPONIBLE EN TU SNAPSHOT. Abre INICIAR-QA-RESTAURADO.cmd y su guía, usa las cuentas privadas del mismo entorno y Español; pulsa Ctrl+F5. Si no está disponible, marca Bloqueado: la candidata de desarrollo no cambia automáticamente tu QA185.'
    sessions='En dos navegadores o perfiles separados entra como Técnico A y Técnico B del ACCESO-PRIVADO.txt. Comprueba la cuenta abajo a la izquierda. Abre en ambos el mismo cliente ficticio compartido; dos pestañas normales comparten sesión y no sirven.'
    end='En Tu resultado selecciona Pass, Not Pass o Bloqueado; anota nombres ficticios, paso y mensaje literal, sin contraseñas/cookies. Arriba pulsa Guardar copia de mis resultados. Tus notas anteriores se conservan.'
    cases=[
      {'id':'QA-63','module':'6 · Colaboración · historia de ubicaciones','title':'Ver nombres registrados de sedes, salas y racks','feature':'inventoryChangeDetailsGui','steps':[intro,sessions,'Usa únicamente objetos NUEVOS: en A, en la barra horizontal superior del inventario, pulsa Gestionar infraestructura; crea una sede, un edificio y una sala con Crear Sede, Crear Edificio y Crear Sala. Escribe nombres QA63 más fecha. Deja B visible sin actualizar mientras A guarda; espera Guardado por el servidor en cada paso.','En B, debajo de la barra del inventario, busca Cambios confirmados en el servidor. En cada tarjeta abre Detalle registrado del cambio y revisa la sección de entidades registradas: Antes vacío en creación y Después con el nombre literal, clase de objeto e ID; el padre es un UUID registrado, no una ruta histórica completa.','En A, bajo el nombre de la sede de prueba, pulsa su Editar, cambia Nombre a QA63 renombrada Ω y pulsa Guardar. En B espera el aviso y abre el detalle: Antes conserva el nombre inicial y Después el nuevo, con el mismo UUID.','En A pulsa Crear Rack en la barra del inventario, escribe QA63 rack y selecciona la sala nueva. Guarda. En su tarjeta pulsa Editar, cambia el nombre a QA63 rack nuevo y guarda. En B compara creación/edición, nombre y tamaño; no debe confundirse el nombre actual del autor con el nombre histórico del rack.','En B pulsa Actualizar vista dentro del aviso. Sólo entonces cambia el árbol cargado y desaparecen los avisos aplicados. Recarga con Ctrl+R y comprueba que siguen los nombres confirmados. Un evento antiguo puede indicar que no se dispone de detalles registrados; no debe inventar datos consultando nombres actuales.',end],'expected':'Los cambios confirmados publican Antes/Después literal y UUID estables. Creación no inventa estado anterior. Los nombres anteriores sobreviven al renombrado, sin notas privadas ni HTML. La vista sólo se relee al solicitarlo.'},
      {'id':'QA-64','module':'6 · Colaboración · equipos y grupos','title':'Ver historia de equipo movido y eliminado','feature':'inventoryChangeDetailsGui','steps':[intro,sessions,'Prepara sólo racks/equipos NUEVOS mediante QA-06. En A pulsa Añadir equipo en la barra superior, elige Equipo de rack y un rack de prueba, escribe QA64 inicial Ω, crea dos grupos RJ45 con prefijos distintos si el formulario lo permite, guarda y espera Guardado por el servidor. Anota el ID del equipo y los IDs de grupo del aviso en B; el número de puerto por sí solo no identifica el grupo.','En A usa Editar en la tarjeta de ese equipo, cambia Nombre a QA64 posterior 東京 y guarda. En B abre Detalle registrado del cambio: Antes conserva QA64 inicial Ω y Después muestra QA64 posterior 東京, con el mismo UUID. La cantidad/prefijo/tipo publicados pertenecen a cada grupoUUID.','En A usa Mover en la tarjeta del equipo y elige otro rack de prueba del mismo cliente, guarda y espera confirmación. En B revisa rackUUID previo/posterior y orden documental; no debe inventarse una U física que no esté registrada. Para tomas/finales puedes repetir QA-33 en dos salas: se muestran salaUUID y tipo, sin inventar rack/circuitos internos.','Sólo sobre este equipo ficticio nuevo: en A pulsa Eliminar, revisa el impacto del cuadro y confirma una vez. En B el aviso de eliminación debe conservar el último nombre registrado, grupos e identidad aunque el equipo ya no exista. No elimines datos originales del backup.','En B pulsa Actualizar vista y después Ctrl+R. El equipo eliminado ya no aparece; los otros equipos/puertos/cables conservan sus datos. Una operación rechazada no publica una modificación confirmada.',end],'expected':'Los avisos conservan historia de nombres y ubicación por IDs; muestran grupos por UUID/tipo/prefijo/cantidad, incluso después del borrado confirmado. No se reconstruye historia con etiquetas actuales. No se inventan U ni circuitos físicos.'},
      {'id':'QA-65','module':'6 · Colaboración · protección de trabajo','title':'Recibir detalles sin perder borrador ni Click-Click','feature':'inventoryChangeDetailsGui','steps':[intro,sessions,'En B pulsa Crear Rack, arriba del inventario; en el cuadro central escribe QA65 borrador y déjalo abierto SIN Guardar. En A renombra un rack ficticio nuevo mediante Editar en su tarjeta y espera Guardado por el servidor. Vuelve a B, mantenlo visible al menos cinco segundos: el texto del borrador debe seguir intacto.','En B pulsa Cancelar en el cuadro. Debajo de la barra del inventario abre el aviso y Detalle registrado del cambio: deben aparecer Antes/Después con los nombres registrados. No debe existir un rack QA65 borrador guardado por recibir el aviso.','En B abre un rack ficticio y haz UN clic en un puerto libre para mantener Click-Click. En A cambia el nombre de otro equipo ficticio y guarda. B recibe el aviso sin perder la selección; Actualizar vista queda bloqueado hasta terminar/cancelar la selección. Pulsa Quitar selección y después Actualizar vista para leer el cambio persistido.','Con Lector en un tercer perfil separado abre el mismo cliente y repite desde A otro renombrado de prueba confirmado. El Lector recibe el detalle y Actualizar vista, sin controles de edición. No retires permisos de cuentas existentes: la revocación se comprueba técnicamente en otra base.','En B pulsa Todos los clientes en la barra izquierda y abre otro cliente autorizado: no arrastra los avisos del anterior. Para idiomas vuelve a Todos los clientes, cambia el selector de la esquina superior derecha a English, Deutsch y Español y repite un renombrado ficticio por idioma: Before/After, Vorher/Nachher y Antes/Después, conservando los nombres literales.',end],'expected':'Polling no guarda, no aplica proyecto automáticamente y conserva borrador/selección. La recarga explícita aplica la revisión confirmada. Lector recibe sólo lo autorizado; cambio de cliente y cierre de sesión retiran el canal anterior. Textos EN/DE/ES, nombres propios literales.'}
    ]
    c['revision']='2026-10-18-grupo428-472';c['cases']=before+cases;c['inventoryChangeDetailsBuilds']=[pair]
    assert c['cases'][:62]==before
    p.write_bytes((json.dumps(c,ensure_ascii=False,indent=2)+'\n').replace('\n','\r\n').encode('utf-8'))
    guide=ROOT/'tools/windows/qa_guide.py';s=guide.read_bytes();old=b"        'clientChangesGui': catalog.get('clientChangesBuilds', []),";new=old+b"\r\n        'inventoryChangeDetailsGui': catalog.get('inventoryChangeDetailsBuilds', []),"
    if b"'inventoryChangeDetailsGui':" not in s:assert old in s;s=s.replace(old,new,1);guide.write_bytes(s)
    test=ROOT/'tools/tests/test_qa_guide.py';s=test.read_bytes();old=b"'QA-60','QA-61','QA-62'))";new=b"'QA-60','QA-61','QA-62','QA-63','QA-64','QA-65'))"
    if old in s:assert s.count(old)==2;s=s.replace(old,new);test.write_bytes(s)
    else:assert s.count(new)==2
    print(json.dumps({'cases':len(c['cases']),'previousCasesUnchanged':c['cases'][:62]==before,'featurePair':pair}))
if __name__=='__main__':main()
